import React from "react";
import img from "../../../assets/img/boozno-b.png";
import { Link } from "react-router-dom";
import "./NotFound.scss";

const ComingSoon = () => {
  return (
    <section className="py-5 not-found-page">
      <div className="container page-wrapper text-center">
        <img src={img} className="mb-4 coming-soon-img" alt="" />
        <h1 className="section-title text-dark-blue mb-3">Coming Soon!</h1>
        <p className="text-light-grey mb-4">The page you are looking for will be available soon. Stay tuned!</p>
        <Link to={"/"}>
          <button className="btn btn-primary border-rad-45 py-3 px-4">Go back to home</button>{" "}
        </Link>
      </div>
    </section>
  );
};

export default ComingSoon;
