import axios from "axios";
import React, { useEffect, useState } from "react";
import Common from "./Common";
import { Spinner } from "react-bootstrap";
import ThankyouModal from "../../common/Modal/ThankyouModal";

const ContactUs = () => {
  const [show, setShow] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [token, setToken] = useState(null);
  const [errors, setErrors] = useState({});

  const formFields = [
    {
      label: "First Name",
      name: "firstName",
      type: "text",
      placeholder: "Your first name",
      colClass: "col-lg-6",
      maxLength: 255,
      pattern: "^[a-zA-Z0-9' ]+$",
    },
    {
      label: "Last Name",
      name: "lastName",
      type: "text",
      placeholder: "Your last name",
      colClass: "col-lg-6",
      maxLength: 255,
      pattern: "^[a-zA-Z0-9' ]+$",
    },
    {
      label: "Email Address",
      name: "emailAddress",
      type: "email",
      placeholder: "Your email address",
      colClass: "col-lg-6",
    },
    {
      label: "Phone Number",
      name: "phoneNumber",
      type: "text",
      placeholder: "Your phone number",
      colClass: "col-lg-6",
      maxLength: 10,
      pattern: "^[0-9]{10}$",
    },
    {
      label: "Write A Message",
      name: "message",
      type: "textarea",
      placeholder: "Write your message",
      colClass: "col-12",
      maxLength: 255,
    },
  ];

  useEffect(() => {
    const fetchToken = async () => {
      try {
        const response = await fetch("https://booznovenueqa.api.dweb.in/api/Account/GetTokenForStaticWebsite/", {
          method: "GET",
          headers: {
            Accept: "application/json",
            transKey: "3vT6zQ2wX8",
            secretKey: "7bD9eF2gH4jK6mNp",
          },
        });

        if (!response.ok) {
          throw new Error(`Error: ${response.status}`);
        }

        const result = await response.json();
        setToken(result.data);
      } catch (error) {
        setError(error.message);
      }
    };

    fetchToken();
  }, []);

  const initialFormData = formFields.reduce((acc, field) => {
    acc[field.name] = "";
    return acc;
  }, {});

  const [formData, setFormData] = useState(initialFormData);

  const inputChangeHandler = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({ ...prevData, [name]: value }));
  };

  const validateForm = () => {
    const newErrors = {};

    formFields.forEach((field) => {
      if (!formData[field.name]) {
        newErrors[field.name] = field.name === "message" ? "Enter correct message" : `Enter correct ${field.label.toLowerCase()}`;
      } else if (field.type === "email" && !/\S+@\S+\.\S+/.test(formData[field.name])) {
        newErrors[field.name] = "Enter a valid email address";
      } else if (field.name === "phoneNumber" && !/^\d{10}$/.test(formData[field.name])) {
        newErrors[field.name] = "Enter a valid 10-digit phone number";
      } else if (field.maxLength && formData[field.name].length > field.maxLength) {
        newErrors[field.name] = `${field.label} should be maximum ${field.maxLength} characters`;
      } else if (field.pattern && !new RegExp(field.pattern).test(formData[field.name])) {
        newErrors[field.name] = `Enter correct ${field.label.toLowerCase()}`;
      }
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true); // Start the spinner

    if (!token) {
      setError("Failed to get the token.");
      setIsSubmitting(false);
      return;
    }

    const contactData = {
      FirstName: formData.firstName,
      LastName: formData.lastName,
      Email: formData.emailAddress,
      Mobile: formData.phoneNumber,
      Message: formData.message,
    };

    try {
      const response = await axios.post("https://booznovenueqa.api.dweb.in/api/Account/StaticWebsiteEmailForContactUs/", contactData, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      setFormData(initialFormData); // Reset the form data
      setShow(true); // Show thank you modal, if needed
    } catch (error) {
      setError("Failed to send contact data.");
      console.error("Failed to send contact data", error);
    } finally {
      setIsSubmitting(false); // Stop the spinner
    }
  };

  return (
    <section className="py-5 h-auto d-flex align-items-center justify-content-center w-100">
      <ThankyouModal show={show} setShow={setShow} />
      <div className="container d-flex align-items-center justify-content-center w-100">
        <div className="dynamic-form-wrapper">
          <div className="row">
            <div className="col-lg-8">
              <h1 className="section-title text-dark-blue text-center text-lg-start">Contact Us</h1>
              <p className="section-subtitle text-center text-lg-start pb-3">Reach out to us for any inquiries or assistance you may need.</p>

              <form onSubmit={handleSubmit} className="custom-forms" noValidate>
                <div className="row mb-3">
                  {formFields.map((data, index) => (
                    <div className={`${data.colClass} mb-4`} key={index}>
                      <label className="form-label text-grey2 ">{data.label}</label>
                      {data.type === "textarea" ? <textarea className={`form-control ${errors[data.name] ? "is-invalid" : ""}`} name={data.name} rows="3" placeholder={data.placeholder} value={formData[data.name]} onChange={inputChangeHandler} required maxLength={data.maxLength}></textarea> : <input autoComplete="off" type={data.type} name={data.name} className={`form-control custom-form-input ${errors[data.name] ? "is-invalid" : ""}`} placeholder={data.placeholder} value={formData[data.name]} onChange={inputChangeHandler} pattern={data.pattern} inputMode={data.name === "phoneNumber" ? "numeric" : undefined} maxLength={data.maxLength} required />}
                      {errors[data.name] && <div className="invalid-feedback">{errors[data.name]}</div>}
                    </div>
                  ))}
                </div>
                <button type="submit" className="btn btn-primary border-rad-45 w-100 py-3">
                  {isSubmitting ? (
                    <>
                      <Spinner animation="border" size="sm" />
                      <span className="ms-2">Submitting...</span>
                    </>
                  ) : (
                    "Submit"
                  )}
                </button>
              </form>
            </div>
            <Common />
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContactUs;
